diff --git a/tests/unit/memory-info-605.test.tsx b/tests/unit/memory-info-605.test.tsx
new file mode 100644
index 0000000..2f41ea4
--- /dev/null
+++ b/tests/unit/memory-info-605.test.tsx
@@ -0,0 +1,50 @@
+/**
+ * T10_F605 (universe U566, design rules R1 and R7): the (i) of Gedächtnis is the app's one
+ * InfoButton, named and behaving like every other: one button, a popup that is a dialog, the name
+ * „Erklärung öffnen: Das Gedächtnis“, and its sheet behind it. On a wide window it stands in the bar,
+ * on the phone in the page (src/screens/Memory.tsx).
+ */
+
+import { render } from "preact";
+import { afterEach, beforeEach, describe, expect, it } from "vitest";
+import { fakeFetch, freshDatabase, pairInStorage, sseResponse } from "./helpers";
+
+pairInStorage();
+const { wide } = await import("../../src/state/layout");
+const { Memory } = await import("../../src/screens/Memory");
+
+const tick = (ms = 0) => new Promise((resolve) => setTimeout(resolve, ms));
+
+let root: HTMLElement;
+beforeEach(async () => {
+  await freshDatabase();
+  fakeFetch(() => sseResponse([]));
+  root = document.createElement("div");
+  document.body.append(root);
+});
+afterEach(() => {
+  render(null, root);
+  root.remove();
+  wide.value = false;
+});
+
+describe("T10_F605: the (i) of Gedächtnis is the shared InfoButton", () => {
+  for (const [where, isWide] of [["on a wide window", true], ["on the phone", false]] as const) {
+    it(`${where}: one button, aria-haspopup dialog, named „Erklärung öffnen“, its sheet behind it`, async () => {
+      wide.value = isWide;
+      render(<Memory />, root);
+      await tick();
+      const buttons = root.querySelectorAll<HTMLButtonElement>("[data-testid=memory-info]");
+      expect(buttons).toHaveLength(1);
+      const button = buttons[0]!;
+      expect(button.tagName).toBe("BUTTON");
+      expect(button.getAttribute("aria-haspopup")).toBe("dialog");
+      expect(button.getAttribute("aria-label")).toBe("Erklärung öffnen: Das Gedächtnis");
+      expect(button.getAttribute("aria-label")).toContain("Erklärung öffnen");
+      expect(document.querySelector("[data-testid=memory-info-sheet]")).toBeNull();
+      button.click();
+      await tick();
+      expect(document.querySelector("[data-testid=memory-info-sheet]")).not.toBeNull();
+    });
+  }
+});
